mappings.PAY.response:
status = 200
  ? (body.outcome = "OK" and $type(body.blId) = "string" and body.blId != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.blId, "code": body.faultCode}
      : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: status = 403 and $type(body.faultCode) = "string" and body.faultCode != ""
  ? {"outcome": "FAILED", "code": body.faultCode, "message": body.faultText}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.INQUIRY.response:
status = 200
  ? (body.outcome = "DUE" and $type(body.billId) = "string" and $type(body.dueAmount) = "string" and $type(body.minAmount) = "string"
      ? {"outcome": "SUCCESS", "partnerRef": body.billId, "code": body.faultCode, "attributes": {"outstanding": body.dueAmount, "minimum": body.minAmount}}
      : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: status = 403 and $type(body.faultCode) = "string" and body.faultCode != ""
  ? {"outcome": "FAILED", "code": body.faultCode, "message": body.faultText}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.STATUS_QUERY.response:
status = 200
  ? (body.outcome = "OK" and $type(body.blId) = "string" and body.blId != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.blId, "code": body.faultCode}
      : body.outcome = "NOK" and $type(body.faultCode) = "string" and body.faultCode != ""
        ? {"outcome": "FAILED", "code": body.faultCode, "message": body.faultText}
        : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: status = 404 and body.outcome = "UNKNOWN"
  ? {"outcome": "NOT_FOUND", "code": body.faultCode, "message": body.faultText}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.REVERSE.response:
status = 200
  ? (body.outcome = "REVERSED" and $type(body.blId) = "string" and body.blId != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.blId, "code": body.faultCode}
      : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: (status = 403 or status = 404) and $type(body.faultCode) = "string" and body.faultCode != ""
  ? {"outcome": "FAILED", "code": body.faultCode, "message": body.faultText}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}
